import orders from './orders.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order. Optionally include the chronological history.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier.' },
          include_history: { type: 'boolean', description: 'Whether to include the chronological history.', default: false }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate args is an object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('order_id' in args)) {
    throw new Error('Missing required field: order_id');
  }

  const orderId = args.order_id;
  if (typeof orderId !== 'string') {
    throw new Error('Field order_id must be a string');
  }

  let includeHistory = false;
  if ('include_history' in args) {
    if (typeof args.include_history !== 'boolean') {
      throw new Error('Field include_history must be a boolean');
    }
    includeHistory = args.include_history;
  }

  if (!(orderId in orders)) {
    throw new Error(`Order not found: ${orderId}`);
  }

  const order = orders[orderId];
  let text = `Order ${orderId}: ${order.status}`;
  if (includeHistory && Array.isArray(order.history)) {
    text += `\nHistory: ${order.history.join(' -> ')}`;
  }

  return { content: [{ type: 'text', text }] };
}
```

